package app.vera.coach.visionbeta;
import android.health.connect.*;
import android.health.connect.datatypes.*;
import android.os.OutcomeReceiver;
import java.time.*;
import java.util.*;
import java.util.function.Consumer;
import org.json.*;
/** Same-origin, fully-contained metrics only: never attribute an entire day to a session. */
final class HealthCardio24 {
 static String sport(int type){switch(type){case ExerciseSessionType.EXERCISE_SESSION_TYPE_BIKING:case ExerciseSessionType.EXERCISE_SESSION_TYPE_BIKING_STATIONARY:return "cycling";case ExerciseSessionType.EXERCISE_SESSION_TYPE_SWIMMING_POOL:case ExerciseSessionType.EXERCISE_SESSION_TYPE_SWIMMING_OPEN_WATER:return "swimming";case ExerciseSessionType.EXERCISE_SESSION_TYPE_RUNNING:case ExerciseSessionType.EXERCISE_SESSION_TYPE_RUNNING_TREADMILL:return "running";case ExerciseSessionType.EXERCISE_SESSION_TYPE_WALKING:return "walking";default:return "";}}
 static final class Metric{String origin,id;long start,end;double value;Metric(String o,String i,long s,long e,double v){origin=o;id=i;start=s;end=e;value=v;}}
 static Double sum(List<Metric> values,String origin,long start,long end){List<Metric> matched=new ArrayList<>();Set<String> ids=new HashSet<>();for(Metric v:values)if(v.origin.equals(origin)&&v.start>=start&&v.end<=end&&v.end>v.start&&Double.isFinite(v.value)&&v.value>=0&&ids.add(v.id))matched.add(v);if(matched.isEmpty())return null;matched.sort(Comparator.comparingLong(v->v.start));long previous=start;double total=0;for(Metric v:matched){if(v.start<previous||v.start-previous>1000)return null;previous=v.end;total+=v.value;}return end-previous<=1000?total:null;}
 static Map<String,NavigableMap<Long,List<Metric>>> index(List<Metric> values){Map<String,NavigableMap<Long,List<Metric>>> out=new HashMap<>();for(Metric m:values)out.computeIfAbsent(m.origin,k->new TreeMap<>()).computeIfAbsent(m.start,k->new ArrayList<>()).add(m);return out;}
 static List<Metric> within(Map<String,NavigableMap<Long,List<Metric>>> index,String origin,long start,long end){List<Metric> out=new ArrayList<>();NavigableMap<Long,List<Metric>> group=index.get(origin);if(group!=null)for(List<Metric> row:group.subMap(start,true,end,false).values())out.addAll(row);return out;}
 static void read(Main a,String ticket,HealthConnectManager manager,TimeInstantRangeFilter range,List<ExerciseSessionRecord> sessions){
  List<Metric> distance=new ArrayList<>(),energy=new ArrayList<>();List<String> warnings=new ArrayList<>();
  Runnable finish=()->{Map<String,NavigableMap<Long,List<Metric>>> distances=index(distance),energies=index(energy);JSONArray arr=new JSONArray();for(ExerciseSessionRecord r:sessions){String origin=r.getMetadata().getDataOrigin().getPackageName();long start=r.getStartTime().toEpochMilli(),end=r.getEndTime().toEpochMilli();if(end<=start)continue;JSONObject o=HealthReader.base(r,r.getStartTime(),r.getStartZoneOffset());String sport=sport(r.getExerciseType());HealthReader.put(o,"sport",sport);if(sport.equals("swimming"))HealthReader.put(o,"swimmingMode",r.getExerciseType()==ExerciseSessionType.EXERCISE_SESSION_TYPE_SWIMMING_POOL?"pool":"open_water");HealthReader.put(o,"exerciseType",r.getExerciseType());HealthReader.put(o,"start",start);HealthReader.put(o,"end",end);HealthReader.put(o,"durationSeconds",(end-start)/1000.0);HealthReader.put(o,"minutes",(end-start)/60000.0);HealthReader.put(o,"title",r.getTitle()==null?"Sesión importada":r.getTitle().toString());HealthReader.put(o,"distanceMeters",sum(within(distances,origin,start,end),origin,start,end));HealthReader.put(o,"energyKcal",sum(within(energies,origin,start,end),origin,start,end));HealthReader.put(o,"metricWarnings",new JSONArray(warnings));arr.put(o);}HealthReader.emit(a,ticket,"workouts",arr);};
  boolean hasCardio=false;for(ExerciseSessionRecord session:sessions)if(!sport(session.getExerciseType()).isEmpty())hasCardio=true;if(!hasCardio){finish.run();return;}
  Runnable calories=()->{if(!HealthReader.allowed(a,"ACTIVE_CALORIES_BURNED")){warnings.add("Sin permiso para leer energía activa.");finish.run();return;}readPage(a,manager,ActiveCaloriesBurnedRecord.class,range,new ArrayList<>(),-1,0,rs->{for(ActiveCaloriesBurnedRecord r:rs)energy.add(new Metric(r.getMetadata().getDataOrigin().getPackageName(),r.getMetadata().getId(),r.getStartTime().toEpochMilli(),r.getEndTime().toEpochMilli(),r.getEnergy().getInCalories()/1000));finish.run();},()->{warnings.add("No se pudo leer energía activa.");finish.run();});};
  if(!HealthReader.allowed(a,"DISTANCE")){warnings.add("Sin permiso para leer distancia.");calories.run();return;}
  readPage(a,manager,DistanceRecord.class,range,new ArrayList<>(),-1,0,rs->{for(DistanceRecord r:rs)distance.add(new Metric(r.getMetadata().getDataOrigin().getPackageName(),r.getMetadata().getId(),r.getStartTime().toEpochMilli(),r.getEndTime().toEpochMilli(),r.getDistance().getInMeters()));calories.run();},()->{warnings.add("No se pudo leer distancia.");calories.run();});
 }
 static <T extends android.health.connect.datatypes.Record> void readPage(Main a,HealthConnectManager manager,Class<T> cls,TimeInstantRangeFilter range,List<T> all,long token,int pages,Consumer<List<T>> done,Runnable failure){
  if(a.isFinishing()||a.isDestroyed())return;if(pages>=20){failure.run();return;}ReadRecordsRequestUsingFilters.Builder<T> builder=new ReadRecordsRequestUsingFilters.Builder<T>(cls).setTimeRangeFilter(range).setPageSize(500);if(token!=-1)builder.setPageToken(token);
  try{manager.readRecords(builder.build(),a.getMainExecutor(),new OutcomeReceiver<ReadRecordsResponse<T>,HealthConnectException>(){public void onResult(ReadRecordsResponse<T> result){for(T row:result.getRecords()){String client=row.getMetadata().getClientRecordId();if(client==null||!client.startsWith("vera23_"))all.add(row);}long next=result.getNextPageToken();if(next==-1)done.accept(all);else if(next==token)failure.run();else readPage(a,manager,cls,range,all,next,pages+1,done,failure);}public void onError(HealthConnectException e){failure.run();}});}catch(Exception e){failure.run();}
 }
}
